// Applied rules: [C5, III④]
// Skipped rules: [C3: Hit [0] is a single per-iteration byte load from the advancing data cursor, not a repeated invariant address-chain load suitable for S2 hoisting; S1 signature lift would be a cross-function rewrite without clear extra leverage here, and the planned III④ in-body slice view already removes the specific raw-pointer post-increment access pattern.; II_vec: Hits [1, 2, 3] stem from the serial reduction shape; applying C5 is the substantive fix. A standalone II_vec canonicalization would not remove the true cross-iteration dependency, so it is subsumed by C5 rather than applied separately.]
unsafe fn update_adler32(
    mut adler: c_uint,
    mut data: *const c_uchar,
    mut len: c_uint,
) -> c_uint {
    let mut s1: c_uint = adler & 0xffff as c_uint;
    let mut s2: c_uint = adler >> 16 as c_uint & 0xffff as c_uint;
    while len != 0 as c_uint {
        let amount: c_uint = if len > 5552 as c_uint {
            5552 as c_uint
        } else {
            len
        };
        let amount_usize = amount as usize;
        let n = amount as u64;
        let s1_old = s1 as u64;

        // SAFETY: `amount` is derived from the caller-provided remaining `len`,
        // is stable for this chunk, and the original loop consumed exactly
        // `amount` bytes from `data` here. The function's caller contract for
        // this unsafe fn must therefore provide `data` as non-null and valid
        // for reads of `amount` bytes, and this shared slice reborrow does not
        // create mutable aliasing.
        let chunk = unsafe { core::slice::from_raw_parts(data, amount_usize) };

        let mut bsum: u64 = 0;
        let mut bwsum: u64 = 0;
        for (j, &byte) in chunk.iter().enumerate() {
            let v = byte as u64;
            bsum = bsum.wrapping_add(v);
            bwsum = bwsum.wrapping_add((j as u64).wrapping_mul(v));
        }

        let s2_chunk = (s2 as u64)
            .wrapping_add(n.wrapping_mul(s1_old))
            .wrapping_add(n.wrapping_mul(bsum))
            .wrapping_sub(bwsum);

        s1 = s1_old.wrapping_add(bsum).wrapping_rem(65521_u64) as c_uint;
        s2 = s2_chunk.wrapping_rem(65521_u64) as c_uint;

        len = len.wrapping_sub(amount);
        data = data.offset(amount as isize);
    }
    return s2 << 16 as c_uint | s1;
}
