        while i != 7 as c_uint {
            let passw_i = passw[i as usize];
            let passh_i = passh[i as usize];
            let passstart_i = passstart[i as usize];
            let adam7_ix = ADAM7_IX[i as usize] as size_t;
            let adam7_iy = ADAM7_IY[i as usize] as size_t;
            let adam7_dx = ADAM7_DX[i as usize] as size_t;
            let adam7_dy = ADAM7_DY[i as usize] as size_t;
